{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Captopril, the closest structural analogue sharing the 3-mercapto-2-methylpropanoyl-proline core, has an absolute oral bioavailability of 62% in healthy subjects after oral solution versus intravenous dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Captopril reached 91% bioavailability in fasting healthy volunteers after a 100 mg oral dose, demonstrating that this thiol-containing proline ACE inhibitor class is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Quinapril, a related ACE inhibitor prodrug, gives 46-52% oral bioavailability of the active principle in humans, supporting high oral bioavailability for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Moexipril, the least bioavailable ACE inhibitor analogue listed, still has 22% oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Perindopril, another ACE inhibitor, has mean oral bioavailability of 65.6-95.1% in healthy volunteers, reinforcing high oral absorption in the class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Argatroban has poor oral bioavailability in humans, but its structure is remote from the query (non-ACE, highly polar), so this low-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the query is a captopril-like thiol ACE inhibitor; captopril and other ACE inhibitors show absolute oral bioavailability mostly 22-95%, and the only low-F analogue (argatroban) is structurally remote.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule (zofenoprilat-like free thiol ACE inhibitor).",
    "The closest analogues are captopril (free thiol) and prodrug ACE inhibitors; direct data for the active acid with a 4-phenylthio substituent are lacking.",
    "Potential first-pass metabolism of the free thiol and the effect of the phenylthio group on absorption are not experimentally resolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

